endofheader:
        switch(saved_status) {
                case TAG3:
                        param->type = TAG_PARAM;        /* tag at the end */
                                                                                /* no break */
                case PARA_NAME:
                case TAG1:
                case TAG2:
                        param->name.len = tmp - param->name.s;
                /* no break */
                case S_EQUAL:
                        /* parameter without '=', e.g. foo */
                        param->value.s = 0;
                        param->value.len = 0;
                        add_param(param, to_b, newparam);
                        saved_status = E_PARA_VALUE;
                        break;
                case S_PARA_VALUE:
                        /* parameter with null value, e.g. foo= */
                        if(status == F_CRLF)
                                param->value.s = tmp - 2;
                        else if(status == F_CR || status == F_LF)
                                param->value.s = tmp - 1;
                        else
                                param->value.s = tmp;
                        param->value.len = 0;
                        add_param(param, to_b, newparam);
                        saved_status = E_PARA_VALUE;
                        break;
                case PARA_VALUE_TOKEN:
                        param->value.len = tmp - param->value.s;
                        add_param(param, to_b, newparam);
                        saved_status = E_PARA_VALUE;
                        break;
                case E_PARA_VALUE:
                        break;
                default:
                        LM_ERR("unexpected end of header, status %d: [%.*s] .\n",
                                        saved_status, (int)(tmp - buffer), ZSW(buffer));
                        goto error;
        }
        *returned_status = saved_status;
        return tmp;
